/// <summary>
/// Manages the encryption keys of environments: creates the key of the current environment, fetches the key of another
/// environment from its key service, exports and imports enrolment ZIP files, and unlocks the private key at execution.
/// </summary>
/// <remarks>
/// See docs/encryption.md for the whole flow.
/// </remarks>
public static class OLK_EnvironmentDataSetupKeyManager
{
    public const str ServicePath        = '/api/services/OLK_EdsServices/OLK_EdsKeyService/getEnrolment';
    public const str TokenUrl           = 'https://login.microsoftonline.com/%1/oauth2/v2.0/token';
    public const str EnvironmentsPath   = '/?mi=OLK_EnvironmentDataSetupTable';
    public const str EnrolmentFileName  = 'enrolment.txt';
    public const str PublicKeyFileName  = 'public-key.xml';
    public const str LockedKeyFileName  = 'private-key.locked.txt';
    public const str ReadMeFileName     = 'README.txt';
}

